/**
 * Bun utility script that validates JSON input from stdin.
 * Exits with code 0 on valid JSON, printing formatted output to stdout.
 * Exits with code 1 on invalid JSON, printing the error to stderr.
 */

const input = await Bun.stdin.text();

if (input.trim() === "") {
  console.error("Error: No input provided");
  process.exit(1);
}

try {
  const parsed = JSON.parse(input);
  console.log(JSON.stringify(parsed, null, 2));
} catch (error) {
  const message = error instanceof Error ? error.message : String(error);
  console.error(`Invalid JSON: ${message}`);
  process.exit(1);
}

import { describe, expect, test } from "bun:test";

describe("validate-json", () => {
  const scriptPath = new URL("./validate-json.ts", import.meta.url).pathname;

  test("valid JSON prints formatted output and exits with code 0", async () => {
    const proc = Bun.spawn(["bun", "run", scriptPath], {
      stdin: new Blob(['{"name":"Alice","age":30}']),
      stdout: "pipe",
      stderr: "pipe",
    });

    const exitCode = await proc.exited;
    const stdout = await new Response(proc.stdout).text();

    expect(exitCode).toBe(0);
    expect(JSON.parse(stdout)).toEqual({ name: "Alice", age: 30 });
  });

  test("invalid JSON prints error to stderr and exits with code 1", async () => {
    const proc = Bun.spawn(["bun", "run", scriptPath], {
      stdin: new Blob(["{not valid json}"]),
      stdout: "pipe",
      stderr: "pipe",
    });

    const exitCode = await proc.exited;
    const stderr = await new Response(proc.stderr).text();

    expect(exitCode).toBe(1);
    expect(stderr).toContain("Invalid JSON");
  });

  test("empty input prints error to stderr and exits with code 1", async () => {
    const proc = Bun.spawn(["bun", "run", scriptPath], {
      stdin: new Blob([""]),
      stdout: "pipe",
      stderr: "pipe",
    });

    const exitCode = await proc.exited;
    const stderr = await new Response(proc.stderr).text();

    expect(exitCode).toBe(1);
    expect(stderr).toContain("No input provided");
  });
});

