/**
 * Add two numbers.
 */
export function add(a: number, b: number): number {
  return a + b;
}

input.new_string:
/**
 * Greet someone formally with their title and name.
 * @param name - The person's name.
 * @param title - The person's title (e.g., "Mr.", "Dr.", "Professor").
 * @returns A formal greeting string.
 */
export function greetFormal(name: string, title: string): string {
  return `Good day, ${title} ${name}. Welcome!`;
}

/**
 * Add two numbers.
 */
export function add(a: number, b: number): number {
  return a + b;
}

input.old_string:
  test("add returns sum of two numbers", () => {
    expect(add(2, 3)).toBe(5);
  });
});

input.new_string:
  test("greetFormal returns formal greeting with title and name", () => {
    expect(greetFormal("Smith", "Dr.")).toBe("Good day, Dr. Smith. Welcome!");
  });

  test("greetFormal works with different titles", () => {
    expect(greetFormal("Alice", "Professor")).toBe(
      "Good day, Professor Alice. Welcome!"
    );
  });

  test("add returns sum of two numbers", () => {
    expect(add(2, 3)).toBe(5);
  });
});

