        "file_path": "/private/tmp/rp1-evals/228ec243/workspace/src/validate-json.test.ts",
        "content": "import { describe, expect, test } from \"bun:test\";\nimport { validateJSON, type ValidationResult } from \"./validate-json\";\n\nfunction expectValid(input: string): void {\n  const result = validateJSON(input);\n  expect(result.valid).toBe(true);\n}\n\nfunction expectInvalid(input: string): ValidationResult & { valid: false } {\n  const result = validateJSON(input);\n  expect(result.valid).toBe(false);\n  return result as ValidationResult & { valid: false };\n}\n\ndescribe(\"validateJSON\", () => {\n  describe(\"valid JSON\", () => {\n    test(\"empty object\", () => {\n      expectValid(\"{}\");\n    });\n\n    test(\"empty array\", () => {\n      expectValid(\"[]\");\n    });\n\n    test(\"simple object with string value\", () => {\n      expectValid('{\"name\": \"Alice\"}');\n    });\n\n    test(\"object with multiple key-value pairs\", () => {\n      expectValid('{\"a\": 1, \"b\": 2, \"c\": 3}');\n    });\n\n    test(\"nested objects\", () => {\n      expectValid('{\"a\": {\"b\": {\"c\": true}}}');\n    });\n\n    test(\"nested arrays\", () => {\n      expectValid(\"[[1, 2], [3, [4, 5]]]\");\n    });\n\n    test(\"mixed nesting\", () => {\n      expectValid('{\"items\": [1, \"two\", {\"three\": 3}], \"ok\": true}');\n    });\n\n    test(\"string with escape sequences\", () => {\n      expectValid('\"hello\\\\nworld\\\\t\\\\r\\\\b\\\\f\\\\\\\\\\\\/\"');\n    });\n\n    test(\"string with unicode escapes\", () => {\n      expectValid('\"\\\\u0041\\\\u004F\\\\u00e9\"');\n    });\n\n    test(\"string with escaped quotes\", () => {\n      expectValid('\"say \\\\\"hello\\\\\"\"');\n    });\n\n    test(\"integer zero\", () => {\n      expectValid(\"0\");\n    });\n\n    test(\"positive integer\", () => {\n      expectValid(\"42\");\n    });\n\n    test(\"negative integer\", () => {\n      expectValid(\"-7\");\n    });\n\n    test(\"decimal number\", () => {\n      expectValid(\"3.14\");\n    });\n\n    test(\"number with exponent\", () => {\n      expectValid(\"1e10\");\n    });\n\n    test(\"number with positive exponent\", () => {\n      expectValid(\"2.5E+3\");\n    });\n\n    test(\"number with negative exponent\", () => {\n      expectValid(\"1.2e-4\");\n    });\n\n    test(\"boolean true\", () => {\n      expectValid(\"true\");\n    });\n\n    test(\"boolean false\", () => {\n      expectValid(\"false\");\n    });\n\n    test(\"null\", () => {\n      expectValid(\"null\");\n    });\n\n    test(\"whitespace around value\", () => {\n      expectValid(\"  \\n\\t { \\n \\\"a\\\" : 1 \\n } \\n \");\n    });\n\n    test(\"bare string\", () => {\n      expectValid('\"hello\"');\n    });\n  });\n\n  describe(\"invalid JSON\", () => {\n    test(\"trailing comma in object\", () => {\n      const result = expectInvalid('{\"a\": 1,}');\n      expect(result.error.message).toContain(\"Expected string key\");\n    });\n\n    test(\"trailing comma in array\", () => {\n      const result = expectInvalid(\"[1, 2,]\");\n      expect(result.error.message).toContain(\"Unexpected character\");\n    });\n\n    test(\"single-quoted string\", () => {\n      const result = expectInvalid(\"{'key': 1}\");\n      expect(result.error.message).toContain(\"Expected string key\");\n    });\n\n    test(\"unquoted keys\", () => {\n      const result = expectInvalid(\"{key: 1}\");\n      expect(result.error.message).toContain(\"Expected string key\");\n    });\n\n    test(\"truncated object\", () => {\n      const result = expectInvalid('{\"a\": 1');\n      expect(result.error.message).toContain(\"Unexpected end of input\");\n    });\n\n    test(\"truncated array\", () => {\n      const result = expectInvalid(\"[1, 2\");\n      expect(result.error.message).toContain(\"Unexpected end of input\");\n    });\n\n    test(\"truncated string\", () => {\n      const result = expectInvalid('\"hello');\n      expect(result.error.message).toContain(\"Unterminated string\");\n    });\n\n    test(\"empty input\", () => {\n      const result = expectInvalid(\"\");\n      expect(result.error.message).toContain(\"Unexpected end of input\");\n    });\n\n    test(\"extra content after value\", () => {\n      const result = expectInvalid(\"true false\");\n      expect(result.error.message).toContain(\"Unexpected character\");\n    });\n\n    test(\"invalid escape in string\", () => {\n      const result = expectInvalid('\"\\\\x41\"');\n      expect(result.error.message).toContain(\"Invalid escape character\");\n    });\n\n    test(\"incomplete unicode escape\", () => {\n      const result = expectInvalid('\"\\\\u00G1\"');\n      expect(result.error.message).toContain(\"Invalid unicode escape\");\n    });\n\n    test(\"leading zeros in number\", () => {\n      const result = expectInvalid(\"01\");\n      expect(result.error.message).toContain(\"Unexpected character\");\n    });\n\n    test(\"bare comma\", () => {\n      const result = expectInvalid(\",\");\n      expect(result.error.message).toContain(\"Unexpected character\");\n    });\n\n    test(\"control character in string\", () => {\n      const result = expectInvalid('\"hello\\x01world\"');\n      expect(result.error.message).toContain(\"Unescaped control character\");\n    });\n  });\n\n  describe(\"error positions\", () => {\n    test(\"reports correct line and column for multiline input\", () => {\n      const input = '{\\n  \"a\": 1,\\n  \"b\": bad\\n}';\n      const result = validateJSON(input);\n      expect(result.valid).toBe(false);\n      if (!result.valid) {\n        expect(result.error.line).toBe(3);\n        expect(result.error.column).toBe(8);\n      }\n    });\n\n    test(\"reports offset for error at start\", () => {\n      const result = validateJSON(\"!\");\n      expect(result.valid).toBe(false);\n      if (!result.valid) {\n        expect(result.error.offset).toBe(0);\n        expect(result.error.line).toBe(1);\n        expect(result.error.column).toBe(1);\n      }\n    });\n  });\n\n  describe(\"performance\", () => {\n    test(\"validates 1MB payload in under 50ms\", () => {\n      const items: string[] = [];\n      const entry = '{\"id\":1,\"name\":\"test\",\"value\":true,\"nested\":{\"a\":[1,2,3]}}';\n      const targetSize = 1024 * 1024;\n      while (items.join(\",\").length + 2 < targetSize) {\n        items.push(entry);\n      }\n      const payload = `[${items.join(\",\")}]`;\n      expect(payload.length).toBeGreaterThanOrEqual(targetSize);\n\n      const start = performance.now();\n      const result = validateJSON(payload);\n      const elapsed = performance.now() - start;\n\n      expect(result.valid).toBe(true);\n      expect(elapsed).toBeLessThan(50);\n    });\n  });\n});\n"
