        "content": "/**\n * High-performance JSON validator using a single-pass state-machine approach.\n * Validates JSON without constructing an object tree, returning structured\n * error results with byte offset, line, and column positions.\n */\n\nexport interface ValidationError {\n  message: string;\n  offset: number;\n  line: number;\n  column: number;\n}\n\nexport type ValidationResult =\n  | { valid: true }\n  | { valid: false; error: ValidationError };\n\nconst WHITESPACE = new Set([0x20, 0x09, 0x0a, 0x0d]); // space, tab, LF, CR\n\nexport function validateJSON(input: string): ValidationResult {\n  let pos = 0;\n  let line = 1;\n  let column = 1;\n\n  function error(message: string): ValidationResult {\n    return { valid: false, error: { message, offset: pos, line, column } };\n  }\n\n  function advance(): number {\n    const ch = input.charCodeAt(pos);\n    pos++;\n    if (ch === 0x0a) {\n      line++;\n      column = 1;\n    } else {\n      column++;\n    }\n    return ch;\n  }\n\n  function peek(): number {\n    return input.charCodeAt(pos);\n  }\n\n  function eof(): boolean {\n    return pos >= input.length;\n  }\n\n  function skipWhitespace(): void {\n    while (!eof() && WHITESPACE.has(peek())) {\n      advance();\n    }\n  }\n\n  function expect(ch: string): ValidationResult | null {\n    if (eof() || String.fromCharCode(peek()) !== ch) {\n      return error(`Expected '${ch}' but got ${eof() ? \"end of input\" : `'${String.fromCharCode(peek())}'`}`);\n    }\n    advance();\n    return null;\n  }\n\n  function expectLiteral(literal: string): ValidationResult | null {\n    for (let i = 0; i < literal.length; i++) {\n      if (eof()) {\n        return error(`Unexpected end of input while parsing '${literal}'`);\n      }\n      if (String.fromCharCode(peek()) !== literal[i]) {\n        return error(`Unexpected character '${String.fromCharCode(peek())}' while parsing '${literal}'`);\n      }\n      advance();\n    }\n    return null;\n  }\n\n  function isDigit(ch: number): boolean {\n    return ch >= 0x30 && ch <= 0x39;\n  }\n\n  function parseString(): ValidationResult | null {\n    const err = expect('\"');\n    if (err) return err;\n\n    while (!eof()) {\n      const ch = peek();\n      if (ch === 0x22) {\n        advance();\n        return null;\n      }\n\n      if (ch < 0x20) {\n        return error(`Unescaped control character in string at offset ${pos}`);\n      }\n\n      if (ch === 0x5c) {\n        advance();\n        if (eof()) return error(\"Unexpected end of input in string escape\");\n\n        const esc = peek();\n        switch (esc) {\n          case 0x22: // \"\n          case 0x5c: // \\\n          case 0x2f: // /\n          case 0x62: // b\n          case 0x66: // f\n          case 0x6e: // n\n          case 0x72: // r\n          case 0x74: // t\n            advance();\n            break;\n          case 0x75: // u\n            advance();\n            for (let i = 0; i < 4; i++) {\n              if (eof()) return error(\"Unexpected end of input in unicode escape\");\n              const hex = peek();\n              if (\n                !isDigit(hex) &&\n                !(hex >= 0x41 && hex <= 0x46) &&\n                !(hex >= 0x61 && hex <= 0x66)\n              ) {\n                return error(`Invalid unicode escape character '${String.fromCharCode(hex)}'`);\n              }\n              advance();\n            }\n            break;\n          default:\n            return error(`Invalid escape character '${String.fromCharCode(esc)}'`);\n        }\n      } else {\n        advance();\n      }\n    }\n\n    return error(\"Unterminated string\");\n  }\n\n  function parseNumber(): ValidationResult | null {\n    if (!eof() && peek() === 0x2d) {\n      advance();\n    }\n\n    if (eof()) return error(\"Unexpected end of input in number\");\n\n    if (peek() === 0x30) {\n      advance();\n    } else if (isDigit(peek())) {\n      while (!eof() && isDigit(peek())) {\n        advance();\n      }\n    } else {\n      return error(`Expected digit but got '${String.fromCharCode(peek())}'`);\n    }\n\n    if (!eof() && peek() === 0x2e) {\n      advance();\n      if (eof() || !isDigit(peek())) {\n        return error(\"Expected digit after decimal point\");\n      }\n      while (!eof() && isDigit(peek())) {\n        advance();\n      }\n    }\n\n    if (!eof() && (peek() === 0x65 || peek() === 0x45)) {\n      advance();\n      if (!eof() && (peek() === 0x2b || peek() === 0x2d)) {\n        advance();\n      }\n      if (eof() || !isDigit(peek())) {\n        return error(\"Expected digit in exponent\");\n      }\n      while (!eof() && isDigit(peek())) {\n        advance();\n      }\n    }\n\n    return null;\n  }\n\n  function parseValue(): ValidationResult | null {\n    skipWhitespace();\n\n    if (eof()) return error(\"Unexpected end of input\");\n\n    const ch = peek();\n\n    if (ch === 0x22) return parseString();\n    if (ch === 0x7b) return parseObject();\n    if (ch === 0x5b) return parseArray();\n    if (ch === 0x74) return expectLiteral(\"true\");\n    if (ch === 0x66) return expectLiteral(\"false\");\n    if (ch === 0x6e) return expectLiteral(\"null\");\n    if (ch === 0x2d || isDigit(ch)) return parseNumber();\n\n    return error(`Unexpected character '${String.fromCharCode(ch)}'`);\n  }\n\n  function parseObject(): ValidationResult | null {\n    const err = expect(\"{\");\n    if (err) return err;\n\n    skipWhitespace();\n\n    if (!eof() && peek() === 0x7d) {\n      advance();\n      return null;\n    }\n\n    while (true) {\n      skipWhitespace();\n      if (eof()) return error(\"Unexpected end of input in object\");\n\n      if (peek() !== 0x22) {\n        return error(`Expected string key but got '${String.fromCharCode(peek())}'`);\n      }\n      const keyErr = parseString();\n      if (keyErr) return keyErr;\n\n      skipWhitespace();\n      const colonErr = expect(\":\");\n      if (colonErr) return colonErr;\n\n      const valErr = parseValue();\n      if (valErr) return valErr;\n\n      skipWhitespace();\n      if (eof()) return error(\"Unexpected end of input in object\");\n\n      if (peek() === 0x7d) {\n        advance();\n        return null;\n      }\n\n      if (peek() === 0x2c) {\n        advance();\n        continue;\n      }\n\n      return error(`Expected ',' or '}' but got '${String.fromCharCode(peek())}'`);\n    }\n  }\n\n  function parseArray(): ValidationResult | null {\n    const err = expect(\"[\");\n    if (err) return err;\n\n    skipWhitespace();\n\n    if (!eof() && peek() === 0x5d) {\n      advance();\n      return null;\n    }\n\n    while (true) {\n      const valErr = parseValue();\n      if (valErr) return valErr;\n\n      skipWhitespace();\n      if (eof()) return error(\"Unexpected end of input in array\");\n\n      if (peek() === 0x5d) {\n        advance();\n        return null;\n      }\n\n      if (peek() === 0x2c) {\n        advance();\n        continue;\n      }\n\n      return error(`Expected ',' or ']' but got '${String.fromCharCode(peek())}'`);\n    }\n  }\n\n  const valErr = parseValue();\n  if (valErr) return valErr;\n\n  skipWhitespace();\n  if (!eof()) {\n    return error(`Unexpected character '${String.fromCharCode(peek())}' after JSON value`);\n  }\n\n  return { valid: true };\n}\n\n/* CLI entrypoint -- only runs when executed directly */\nif (import.meta.main) {\n  async function main(): Promise<void> {\n    let input: string;\n\n    const filePath = process.argv[2];\n    if (filePath) {\n      const file = Bun.file(filePath);\n      const exists = await file.exists();\n      if (!exists) {\n        console.error(`Error: file not found: ${filePath}`);\n        process.exit(2);\n      }\n      input = await file.text();\n    } else {\n      input = await Bun.stdin.text();\n    }\n\n    const result = validateJSON(input);\n    if (result.valid) {\n      console.log(\"Valid JSON\");\n      process.exit(0);\n    } else {\n      const { message, line, column } = result.error;\n      console.error(`Invalid JSON at line ${line}, column ${column}: ${message}`);\n      process.exit(1);\n    }\n  }\n\n  main();\n}\n"
